// TH15 v1.00b Extra (stage 7) BossCard2 — 地球「邪穢在身」
// Source: st07bs.ecl.txt:1586-1646 (BossCard2), 1648-1714 (BossCard2_at),
//         1716-1734 (BossCard2_at2). Extra / rank 4 only: source !O (task 4,4).
// Card frame 0 = training-segment start. The 120-frame opening buffer spawns the
// real boss at card frame 123, whose first instruction (source entry t=0) is card
// 124; source timerReset t=4 (1599) is therefore card 128. The source 4200-frame
// window ends at card 4328; the shell phase ends at card 4327 (run log).
// TIME_LIMIT=4324 (120 buffer + 4200 + 4 pre-timerReset margin) per task.md.

const TIME_LIMIT: int = 4324;
const OPENING_BUFFER: int = 120;

// TH15 synthetic bullet aliases (copy of the needed lines from
// transcribe/th15/touhou-bullets.ecl). Source type 16/27, colors kept.
const TH15_STAR_R: int = 608;        // source type 16 (BossCard2_at2)
const TH15_FIREBALL_BLUE: int = 784; // source type 27 (BossCard2_at)

const AT2_COLOR: int = 6;  // etSprite(0,16,6)
const AT_COLOR: int = 0;   // etSprite(1,27,0)

// Source BossCard2_at EX record 3 is LASER(Line) and record 4 is its paired data.
// d!=0 deletes the parent bullet; the parent EX WAIT is record 2. This xform only
// reproduces the parent bullet's death time (the approved birth ANIM wait is skipped,
// so the WAIT is measured from spawn). laser_schedule creates the child laser.
xformdef DIE_AFTER(frames: int) {
    wait(frames);
    set_life(1);
}

// Child of source EX_LASER (type 0x8000000, a=0 Line):
//   b=8 sprite, c=6 color, d=1 delete parent, r=999999 aim player, s=1 speed,
//   m=32 line length; paired record: r2=0, s2=16 width, m2=0 distance,
//   c2=8 -> child copies parent EX from index 8 (ACCEL a=120 r=0.025, angle kept).
// Target line laser is constant-width: 判定段 0.1L..0.9L (flags 0x2 clear) and
// w=16 -> 2*(w/4)=8 judgement width. n=96 is a length-related source field whose
// consumer is not defined in the supplied rules; the L=m=32 reading is reported.
async sub laser_schedule(wait_frames: int, spd: fx, x0: fx, y0: fx, stop_frame: int) {
    wait(wait_frames - 1); // spawned tasks first run one frame after the bullet's spawn
    if $frame >= stop_frame { return; }
    var lx: fx = x0;
    var ly: fx = y0 - spd * wait_frames;
    var ang: angle = atan2($player_y - ly, $player_x - lx);
    var h: int = laser(6, lx, ly, ang, 28.8fx, 8fx, 0, 600, 0);
    lz_start(h, 3.2fx);
    // ACCEL: speed 1.0 -> 4.0 over 120 ticks, direction preserved.
    var v: fx = 1fx;
    var n: int = 0;
    while n < 120 && $frame < stop_frame {
        v = v + 0.025fx;
        lx = lx + v * cos(ang);
        ly = ly + v * sin(ang);
        lz_origin(h, lx, ly);
        n = n + 1;
        wait(1);
    }
    // Source has no further EX record; keep the beam until it leaves the field.
    while lx > -260fx && lx < 260fx && ly > -120fx && ly < 580fx && $frame < stop_frame {
        lx = lx + v * cos(ang);
        ly = ly + v * sin(ang);
        lz_origin(h, lx, ly);
        wait(1);
    }
    lz_cancel(h);
}

// One source BossCard2_at firing iteration (1669-1678 / 1684-1693 / 1699-1708):
// one RAND for the WAIT, one RANDF2 for speed, one RANDF2 for the offset, then the
// same bullet fired at +A and -A (both share WAIT/speed/|offset|).
sub shot_pair(b: fx, stop_frame: int) {
    var w: int = 120 + rand(120); // source 120 + $RAND % 120
    var spd: fx = 1.6fx + ((rand(65536) - 32768) as fx / 32768) * 0.2fx; // RANDF2*0.2
    var a: fx = b + ((rand(65536) - 32768) as fx / 32768) * 16fx;        // RANDF2*16
    // EX record 0 ANIM a=1 birth back-off: position -= 4*velocity (velocity is up).
    var y0: fx = 448fx + 4fx * spd;
    spawn laser_schedule(w, spd, a, y0, stop_frame);
    _ = fire(TH15_FIREBALL_BLUE, AT_COLOR, a, y0, spd, 270deg, DIE_AFTER(w), none);
    spawn laser_schedule(w, spd, 0fx - a, y0, stop_frame);
    _ = fire(TH15_FIREBALL_BLUE, AT_COLOR, 0fx - a, y0, spd, 270deg, DIE_AFTER(w), none);
}

// Source 1666-1683: $D/$E/$F = 20 iterations of wait(15). start/goal are the
// floatTime(0,%B,300,9,...) endpoints; source mode 9 is EASE_QUAD_IN_OUT and the
// k-th shot (k=0..19) reads B after 15*k of the 300 interpolation frames.
sub burst(start: fx, goal: fx, stop_frame: int) {
    var d: int = 20;
    var k: int = 0;
    while d > 0 && $frame < stop_frame {
        var t: fx = (k as fx) / 20;
        var f: fx = 0fx;
        if t < 0.5fx {
            f = 2fx * t * t;
        } else {
            f = 1fx - 2fx * (1fx - t) * (1fx - t);
        }
        shot_pair(start + (goal - start) * f, stop_frame);
        d = d - 1;
        k = k + 1;
        wait(15);
    }
}

// Source BossCard2_at: wait(60), configure emitter, %B=180, $C=10000, then the
// D/E/F groups repeat forever. The synchronous call never returns inside the card,
// so BossCard2's trailing wait(90)/moveRand(30,4,2.0)/wait(40) is unreachable and
// the boss stays at its entry position (0,128).
sub at_loop() {
    wait(60); // 1651
    var stop: int = TIME_LIMIT; // segment ends HERE; source switches to Boss3 at timerReset+4200
    var c: int = 10000;             // 1664 $C = 10000
    while c > 0 && $frame < stop {
        c = c - 1;
        burst(180fx, 180fx, stop); // $B = 180 constant (1663/1681)
        burst(180fx, 96fx, stop);  // floatTime 180 -> 96 (1681)
        burst(96fx, 180fx, stop);  // floatTime 96 -> 180 (1696)
    }
    loop { wait(1); } // keep the boss (and its laser tasks) alive past the segment
}

// Source BossCard2_at2 (1716-1734): every 40 frames, if the player is closer than
// 128, one 32-way fixed-direction ring rotated by RANDRAD. etAim(0,3) is a fixed
// direction ring; the random rotation is a full-circle uniform angle.
async sub at2_loop() {
    loop {
        if dist($player_x - $self_x, $player_y - $self_y) < 128fx {
            sh_reset(0); // 1721 etNew(0)
            sh_sprite(0, TH15_STAR_R, AT2_COLOR);
            sh_ring(0, 1);
            sh_aim(0, 0);
            sh_count(0, 32, 1);
            sh_angle(0, rand(65536) as angle, 0deg); // %RANDRAD
            sh_speed(0, 1.5fx, 0fx);
            sh_fire(0);
        }
        wait(40);
    }
}

// Source BossCard2 entry, with the approved TH15 standalone shell:
// - common Boss frame state: invuln/box; speed and position are already (0,128)
//   and the boss never moves in this card, so the moveLimit rectangle and the
//   zero-length moveVel/movePosTime calls need no target write.
// - etCancel(640) at t=0 maps to a one-frame circular clear.
// - chapter/stat/sound/anim/spell declarations and stats are approved omissions;
//   setInterrupt slot 0 is represented by the shell phase timer.
async sub source_enemy() {
    set_invuln(65535); // training shell: no player DPS, body collision kept
    set_hitbox(24fx);  // Boss frame setHitbox(48,48) -> first value * 0.5
    set_hurtbox(20fx); // Boss frame setHurtbox(40,40) -> 20
    clear_bullets_at(0fx, 128fx, 640fx, 0); // 1589-1590 etCancel(640)
    wait(4);  // chapter at +2 omitted; prep at t=4
    wait(90); // 1599-1623 prep, then +90 to t=94
    spawn at2_loop(); // 1627
    at_loop();        // 1628-1634, synchronous and effectively endless
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 20000, 0, 0, 0, source_enemy);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
